// Turns docs/API.md into site/docs.generated.ts (the HTML body of /docs) and
// docs/LAUNCH_POST.md into site/post.generated.ts (the /blog post, TCS-14).
// A small Markdown subset, no dependency: headings, paragraphs, lists
// (- and 1.), fenced code, tables, `code`, [text](url) links and a paragraph
// that is one bare URL.
//
//   npm run gen:docs              write both generated files
//   npm run gen:docs -- --check   exit 1 if either committed file is stale
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");

const esc = (s) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

function inline(text) {
  // Split out code spans first so nothing inside them is parsed.
  return text
    .split(/(`[^`]+`)/)
    .map((part) => {
      if (part.startsWith("`") && part.endsWith("`") && part.length > 1) return `<code>${esc(part.slice(1, -1))}</code>`;
      return esc(part).replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, t, u) => `<a href="${u}">${t}</a>`);
    })
    .join("");
}

const slug = (s) =>
  s.toLowerCase().replace(/`/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

const cells = (line) => line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());

export function render(md) {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out = [];
  let i = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim() === "") {
      i++;
      continue;
    }
    if (line.startsWith("```")) {
      const body = [];
      i++;
      while (i < lines.length && !lines[i].startsWith("```")) body.push(lines[i++]);
      i++;
      out.push(`<pre><code>${esc(body.join("\n"))}</code></pre>`);
      continue;
    }
    const h = /^(#{1,3}) (.+)$/.exec(line);
    if (h) {
      const n = h[1].length;
      out.push(`<h${n} id="${slug(h[2])}">${inline(h[2])}</h${n}>`);
      i++;
      continue;
    }
    if (line.startsWith("|") && i + 1 < lines.length && /^\|[\s:|-]+\|$/.test(lines[i + 1].trim())) {
      const head = cells(line);
      i += 2;
      const rows = [];
      while (i < lines.length && lines[i].startsWith("|")) rows.push(cells(lines[i++]));
      out.push(
        `<div class="table"><table><thead><tr>${head.map((c) => `<th scope="col">${inline(c)}</th>`).join("")}</tr></thead><tbody>` +
          rows.map((r) => `<tr>${r.map((c) => `<td>${inline(c)}</td>`).join("")}</tr>`).join("") +
          "</tbody></table></div>",
      );
      continue;
    }
    const list = /^(- |\d+\. )/.exec(line);
    if (list) {
      const tag = list[1] === "- " ? "ul" : "ol";
      const items = [];
      while (i < lines.length && /^(- |\d+\. )/.test(lines[i])) items.push(lines[i++].replace(/^(- |\d+\. )/, ""));
      out.push(`<${tag}>${items.map((t) => `<li>${inline(t)}</li>`).join("")}</${tag}>`);
      continue;
    }
    const para = [];
    while (i < lines.length && lines[i].trim() !== "" && !/^(```|#{1,3} |\||- |\d+\. )/.test(lines[i])) para.push(lines[i++]);
    const text = para.join(" ");
    if (/^https?:\/\/[^\s<>"'`]+$/.test(text)) out.push(`<p><a href="${esc(text)}">${esc(text)}</a></p>`);
    else out.push(`<p>${inline(text)}</p>`);
  }
  return out.join("\n");
}

const read = (src) => readFileSync(resolve(root, src), "utf8");

function docsModule(src) {
  return `// GENERATED by scripts/gen-docs.mjs from ${src}. Do not edit.\n` + `export const DOCS_HTML = ${JSON.stringify(render(read(src)))};\n`;
}

// The post's title is its first "# " heading. POST_HASH (the first 32 hex of
// the SHA-256 of the HTML) is the page's ETag.
function postModule(src) {
  const md = read(src);
  const title = /^# (.+)$/m.exec(md)?.[1];
  if (!title) throw new Error(`${src} has no "# " heading`);
  const html = render(md);
  const hash = createHash("sha256").update(html).digest("hex").slice(0, 32);
  return (
    `// GENERATED by scripts/gen-docs.mjs from ${src}. Do not edit.\n` +
    `export const POST_TITLE = ${JSON.stringify(title)};\n` +
    `export const POST_HTML = ${JSON.stringify(html)};\n` +
    `export const POST_HASH = ${JSON.stringify(hash)};\n`
  );
}

const TARGETS = [
  { out: "site/docs.generated.ts", code: () => docsModule("docs/API.md") },
  { out: "site/post.generated.ts", code: () => postModule("docs/LAUNCH_POST.md") },
];

function current(outPath) {
  try {
    return readFileSync(outPath, "utf8");
  } catch {
    return ""; // a missing file counts as stale
  }
}

const check = process.argv.includes("--check");
let stale = false;
for (const t of TARGETS) {
  const code = t.code();
  const outPath = resolve(root, t.out);
  if (check) {
    if (current(outPath) !== code) {
      console.error(`${t.out} is stale. Run: npm run gen:docs`);
      stale = true;
    }
  } else {
    writeFileSync(outPath, code);
    console.log(`wrote ${outPath}`);
  }
}
if (stale) process.exit(1);
if (check) console.log("docs page and post are up to date");
